```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    static class Edge implements Comparable<Edge> {
        int diff;
        int pos;

        Edge(int diff, int pos) {
            this.diff = diff;
            this.pos = pos;
        }

        @Override
        public int compareTo(Edge other) {
            return this.diff - other.diff;
        }
    }

    static class DSU {
        int[] parent;
        int[] size;
        int maxSize;

        DSU(int n) {
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
            maxSize = 1;
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;

            // 按大小合并
            if (size[rx] < size[ry]) {
                int tmp = rx;
                rx = ry;
                ry = tmp;
            }
            parent[ry] = rx;
            size[rx] += size[ry];
            if (size[rx] > maxSize) {
                maxSize = size[rx];
            }
        }
    }

    static int[] solveOneCase(int n, int[] arr) {
        Edge[] edges = new Edge[n - 1];
        for (int i = 0; i < n - 1; i++) {
            int diff = Math.abs(arr[i] - arr[i + 1]);
            edges[i] = new Edge(diff, i + 1); // 连接 i+1 和 i+2
        }

        Arrays.sort(edges);

        DSU dsu = new DSU(n);
        int[] ans = new int[n + 1]; // ans[k] 存 k 对应的答案
        int idx = 0;

        for (int k = 1; k <= n; k++) {
            while (idx < edges.length && edges[idx].diff <= k) {
                int pos = edges[idx].pos;
                dsu.union(pos, pos + 1);
                idx++;
            }
            ans[k] = dsu.maxSize;
        }

        return ans;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int t = Integer.parseInt(br.readLine().trim());
        while (t-- > 0) {
            int n = Integer.parseInt(br.readLine().trim());
            int[] arr = new int[n];
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int i = 0; i < n; i++) {
                arr[i] = Integer.parseInt(st.nextToken());
            }
            int[] ans = solveOneCase(n, arr);
            for (int k = 1; k <= n; k++) {
                if (k > 1) sb.append(' ');
                sb.append(ans[k]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
