#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

struct Edge {
    int diff;
    int pos;

    bool operator<(const Edge& other) const {
        return diff < other.diff;
    }
};

class DSU {
public:
    vector<int> parent;
    vector<int> sz;
    int maxSize;

    DSU(int n) {
        parent.resize(n + 1);
        sz.assign(n + 1, 1);
        for (int i = 1; i <= n; i++) {
            parent[i] = i;
        }
        maxSize = 1;
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unite(int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) return;

        // 按大小合并，小集合挂到大集合上
        if (sz[rx] < sz[ry]) {
            swap(rx, ry);
        }
        parent[ry] = rx;
        sz[rx] += sz[ry];
        if (sz[rx] > maxSize) {
            maxSize = sz[rx];
        }
    }
};

vector<int> solveOneCase(int n, const vector<int>& arr) {
    vector<Edge> edges;
    for (int i = 0; i < n - 1; i++) {
        int diff = abs(arr[i] - arr[i + 1]);
        edges.push_back({diff, i + 1}); // 连接 i+1 和 i+2
    }

    sort(edges.begin(), edges.end());

    DSU dsu(n);
    vector<int> ans(n + 1);
    int idx = 0;
    int m = (int)edges.size();

    for (int k = 1; k <= n; k++) {
        while (idx < m && edges[idx].diff <= k) {
            int pos = edges[idx].pos;
            dsu.unite(pos, pos + 1);
            idx++;
        }
        ans[k] = dsu.maxSize;
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> arr(n);
        for (int i = 0; i < n; i++) {
            cin >> arr[i];
        }
        vector<int> ans = solveOneCase(n, arr);
        for (int k = 1; k <= n; k++) {
            if (k > 1) cout << ' ';
            cout << ans[k];
        }
        cout << '\n';
    }

    return 0;
}
